WITH base AS (SELECT id, store_id, product_id, units, LEAST(units, revenue) AS least_units_revenue, CASE WHEN revenue >= 3500 THEN 'High' WHEN revenue >= 700 THEN 'Medium' ELSE 'Low' END AS revenue_level FROM store_sales WHERE sale_date >= DATE '2024-04-11' AND product_id IN (7, 10)) SELECT store_id, product_id, COUNT(DISTINCT store_id) AS distinct_store_ids, ROUND(AVG(units), 2) AS avg_units, COUNT(*) AS row_count, COUNT(DISTINCT product_id) AS distinct_product_ids, ROUND(AVG(units), 2) AS avg_units_2 FROM base GROUP BY store_id, product_id;
